fn get_column(input: &Vec<Vec<i8>>, j: usize, _m: usize, n: usize) -> Vec<i8> {
    // Collect the j-th element from each of the n rows
    let mut col = Vec::with_capacity(n);
    for i in 0..n {
        col.push(input[i][j]);
    }
    col
}

fn column_stack(input: Vec<Vec<i8>>, m: usize, n: usize) -> Vec<Vec<i8>> {
    // Build a new matrix with m rows, each being one of the columns of the input
    let mut result = Vec::with_capacity(m);
    for j in 0..m {
        result.push(get_column(&input, j, m, n));
    }
    result
}

// Example usage and test
fn main() {
    let input = vec![
        vec![1, 2, 3],
        vec![4, 5, 6],
    ];
    // input has n = 2 rows and m = 3 columns
    let transposed = column_stack(input, 3, 2);
    assert_eq!(transposed, vec![
        vec![1, 4],
        vec![2, 5],
        vec![3, 6],
    ]);
    println!("Transpose successful: {:?}", transposed);
}